package com.example.proyectolp.service;
import javafx.beans.property.*;
public final class NotificationService {private static final NotificationService INSTANCE=new NotificationService();private final StringProperty message=new SimpleStringProperty("");private final javafx.stage.Popup popup=new javafx.stage.Popup();private final javafx.scene.control.Label toast=new javafx.scene.control.Label();private final javafx.animation.PauseTransition hide=new javafx.animation.PauseTransition(javafx.util.Duration.seconds(5));private NotificationService(){toast.setStyle("-fx-background-color: #173b2a; -fx-text-fill: white; -fx-padding: 12 18; -fx-background-radius: 8;");toast.setWrapText(true);toast.setMaxWidth(380);popup.getContent().add(toast);hide.setOnFinished(e->popup.hide());}public static NotificationService getInstance(){return INSTANCE;}public StringProperty messageProperty(){return message;}public String getMessage(){return message.get();}public void clear(){Runnable action=()->{message.set("");hide.stop();popup.hide();};if(javafx.application.Platform.isFxApplicationThread())action.run();else javafx.application.Platform.runLater(action);}public void show(String text){Runnable update=()->{String display=popup.isShowing()&&!message.get().isBlank()?message.get()+" · "+text:text;message.set(display);toast.setText(display);javafx.stage.Window.getWindows().stream().filter(javafx.stage.Window::isShowing).findFirst().ifPresent(w->{if(!popup.isShowing())popup.show(w,w.getX()+Math.max(20,w.getWidth()-410),w.getY()+20);hide.playFromStart();});};if(javafx.application.Platform.isFxApplicationThread())update.run();else javafx.application.Platform.runLater(update);}}
